function renderTasks(){const list=filterReminders(state.tasks,state.filter,state.query),s=getSummary(state.tasks);$('#pendingCount').textContent=s.pending;$('#todayCount').textContent=s.today;$('#doneCount').textContent=s.done;$('#pendingDetail').textContent=s.overdue?`${s.overdue} vencida${s.overdue===1?'':'s'} incluida${s.overdue===1?'':'s'}`:'esta semana';$('#taskEmpty').hidden=!!list.length;$('#reminderList').innerHTML=list.map(x=>{const p=person(x.personId);return `<article class="reminder ${x.completed?'completed':''}" data-id="${x.id}"><button class="check" data-task="toggle" aria-label="${x.completed?'Marcar como pendiente':'Marcar como terminada'}">${x.completed?icon('check'):''}</button><div class="reminder-content"><div class="reminder-title"><h3>${esc(x.title)}</h3><span class="priority ${x.priority}">${({high:'Alta',medium:'Media',low:'Baja'})[x.priority]}</span></div>${x.notes?`<p>${esc(x.notes)}</p>`:''}<div class="meta"><span>${icon('clock')} ${fmt(x)}</span>${p?`<span>${icon('user')} ${esc(p.name)}</span>`:''}</div><div class="tags">${x.tags.map(t=>`<span>#${esc(t)}</span>`).join('')}</div></div><div class="item-actions"><button data-task="edit" aria-label="Editar">${icon('pencil-simple')}</button><button data-task="delete" aria-label="Eliminar">${icon('trash')}</button></div></article>`}).join('')}
