function renderNotes(){const q=$('#noteSearch').value.toLowerCase(),items=state.notes.filter(n=>(n.title+' '+n.content).toLowerCase().includes(q));$('#notesGrid').innerHTML=items.length?items.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(n=>`<article class="note-card ${n.color}" data-id="${n.id}"><div><h3>${esc(n.title)}</h3><p>${esc(n.content).replace(/\n/g,'<br>')}</p></div><footer><small>${new Date(n.updatedAt).toLocaleDateString('es-MX')}</small><span><button data-note="edit" aria-label="Editar">${icon('pencil-simple')}</button><button data-note="delete" aria-label="Eliminar">${icon('trash')}</button></span></footer></article>`).join(''):`<div class="empty-state"><div>${icon('note-blank')}</div><h2>No hay notas</h2></div>`}
function renderCalendar(){const y=state.calendar.getFullYear(),m=state.calendar.getMonth(),first=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate();$('#monthTitle').textContent=new Intl.DateTimeFormat('es-MX',{month:'long',year:'numeric'}).format(state.calendar);let html='';for(let i=0;i<first;i++)html+='<div class="day muted"></div>';for(let d=1;d<=days;d++){const key=localDateKey(new Date(y,m,d)),items=state.tasks.filter(t=>t.date===key);html+=`<button class="day ${key===localDateKey()?'today':''} ${key===state.selectedDate?'selected':''}" data-date="${key}"><b>${d}</b><span class="dots">${items.slice(0,3).map(t=>`<i class="${t.priority} ${t.completed?'completed':''}"></i>`).join('')}</span></button>`}$('#calendarGrid').innerHTML=html;const items=state.tasks.filter(t=>t.date===state.selectedDate).sort((a,b)=>a.time.localeCompare(b.time));$('#dayAgenda').innerHTML=`<h2>${new Date(state.selectedDate+'T12:00').toLocaleDateString('es-MX',{weekday:'long',day:'numeric',month:'long'})}</h2>`+(items.length?items.map(t=>`<div class="agenda-row ${t.completed?'completed':''}"><time>${t.time}</time><span><b>${esc(t.title)}</b><small>${t.tags.map(x=>'#'+esc(x)).join(' ')}</small></span></div>`).join(''):'<p>No hay tareas para este día.</p>')}
function renderAll(){renderTasks();renderPeople();renderNotes();renderCalendar();updateAiStatus()}
function openTask(item){$('#taskForm').reset();$('#taskId').value=item?.id||'';$('#titleInput').value=item?.title||'';$('#taskNotes').value=item?.notes||'';const d=new Date(Date.now()+3600000);$('#dateInput').value=item?.date||localDateKey(d);$('#timeInput').value=item?.time||`${String(d.getHours()).padStart(2,'0')}:00`;$('#priorityInput').value=item?.priority||state.preferences.defaultPriority||'medium';$('#repeatInput').value=item?.repeat||'none';$('#personInput').innerHTML='<option value="">Sin asignar</option>'+state.people.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');$('#personInput').value=item?.personId||'';$('#tagsInput').value=(item?.tags||[]).join(', ');$('#reminderMinutes').value=String(item?.reminderMinutes??state.preferences.defaultReminderMinutes??0);$('#taskError').textContent='';loadRepeatControls(item);$('#taskDialog').showModal()}
