function openNote(n){$('#noteForm').reset();$('#noteId').value=n?.id||'';$('#noteTitle').value=n?.title||'';$('#noteContent').value=n?.content||'';$('#noteColor').value=n?.color||'purple';$('#noteDialog').showModal()}
async function notify(item){const due=toDateTime(item);if(due<=new Date()||item.completed)return;try{if(globalThis.Capacitor?.isNativePlatform?.()){const LocalNotifications=await localNotificationsPlugin();if((await LocalNotifications.requestPermissions()).display!=='granted'){toast('Activa las notificaciones para recibir recordatorios.');return}const notifications=[],Alarm=globalThis.Capacitor?.Plugins?.Alarm;if(item.priority==='high'&&Alarm)await Alarm.schedule(alarmPayload(item));else notifications.push({id:hash(item.id+':due'),title:item.title,body:item.notes||'Tienes una tarea pendiente',schedule:{at:due,allowWhileIdle:true},actionTypeId:'TASK_ACTIONS',channelId:'reminders',extra:{reminderId:item.id,kind:'due'}});const minutes=Number(item.reminderMinutes||0),early=new Date(due.getTime()-minutes*60000);if(minutes>0&&early>new Date())notifications.push({id:hash(item.id+':early'),title:'Próximamente: '+item.title,body:'Faltan '+friendlyMinutes(minutes)+' para esta tarea.',schedule:{at:early,allowWhileIdle:true},actionTypeId:'TASK_ACTIONS',channelId:'reminders',extra:{reminderId:item.id,kind:'early'}});if(notifications.length)await LocalNotifications.schedule({notifications})}}catch(e){console.warn(e);toast('No se pudo programar el aviso.')}}
const hash=(v)=>[...v].reduce((h,c)=>(h*31+c.charCodeAt(0))|0,7)&0x7fffffff;
async function localNotificationsPlugin(){return globalThis.Capacitor?.Plugins?.LocalNotifications||(await import('@capacitor/local-notifications')).LocalNotifications}
const friendlyMinutes=m=>m===1440?'un día':m===60?'una hora':m+' minutos';
function alarmPayload(item){const repeating=item.repeat&&item.repeat!=='none',nextAt=repeating?toDateTime(nextOccurrence(item)).getTime():0;return{taskId:item.id,title:item.title,at:toDateTime(item).getTime(),repeating,nextAt}}
function setupNotificationControls(){const label=document.createElement('label');label.innerHTML='Avisar antes<select id="reminderMinutes"><option value="0">A la hora indicada</option><option value="5">5 minutos antes</option><option value="10">10 minutos antes</option><option value="15">15 minutos antes</option><option value="30">30 minutos antes</option><option value="60">1 hora antes</option><option value="1440">1 día antes</option></select>';$('#taskError').before(label)}
