function setupRepeatControls(){const box=document.createElement('div');box.id='repeatDetails';box.className='repeat-details';box.hidden=true;box.innerHTML='<div id="repeatDaysBox"><span>Días de repetición</span><div class="weekday-picker">'+[['0','D'],['1','L'],['2','M'],['3','M'],['4','J'],['5','V'],['6','S']].map(([v,t])=>`<label><input type="checkbox" name="repeatDay" value="${v}"><span>${t}</span></label>`).join('')+'</div></div><div id="repeatIntervalBox" class="form-grid"><label>Cada<input id="repeatInterval" type="number" min="1" max="365" value="1"></label><label>Periodo<select id="repeatUnit"><option value="days">Día(s)</option><option value="weeks">Semana(s)</option><option value="months">Mes(es)</option></select></label></div>';$('#priorityInput').closest('.form-grid').after(box);$('#repeatInput').onchange=toggleRepeatControls}
