function loadRepeatControls(item){$$('[name="repeatDay"]').forEach(x=>x.checked=(item?.repeatDays||[]).map(Number).includes(Number(x.value)));$('#repeatInterval').value=String(item?.repeatInterval||1);$('#repeatUnit').value=item?.repeatUnit||'days';toggleRepeatControls()}
setupRepeatControls();
async function completeFromNotification(id){const item=state.tasks.find(x=>x.id===id);if(!item||item.completed)return;item.completed=true;await cancel(item);if(item.repeat!=='none'){const next=nextOccurrence(item);next.tags=item.tags;next.personId=item.personId;next.reminderMinutes=item.reminderMinutes;state.tasks.push(next);await notify(next)}save();renderAll()}
async function skipOccurrence(id){const index=state.tasks.findIndex(x=>x.id===id);if(index<0)return;const item=state.tasks[index];if(!item.repeat||item.repeat==='none')return completeFromNotification(id);await cancel(item);const next=nextOccurrence(item);next.id=item.id;next.createdAt=item.createdAt;state.tasks[index]=next;save();await notify(next);renderAll();toast('Repetición omitida')}
async function snoozeNotification(id,minutes){const item=state.tasks.find(x=>x.id===id);if(!item||item.completed)return;const LocalNotifications=await localNotificationsPlugin();await LocalNotifications.cancel({notifications:[{id:hash(item.id+':snooze')}]});await LocalNotifications.schedule({notifications:[{id:hash(item.id+':snooze'),title:item.title,body:'Recordatorio pospuesto',schedule:{at:new Date(Date.now()+minutes*60000),allowWhileIdle:true},actionTypeId:'TASK_ACTIONS',channelId:'reminders',extra:{reminderId:item.id,kind:'snooze'}}]})}
async function initNativeNotifications(){if(!globalThis.Capacitor?.isNativePlatform?.())return;try{const LocalNotifications=await localNotificationsPlugin();await LocalNotifications.createChannel({id:'reminders',name:'Recordatorios',description:'Avisos de tareas y agenda',importance:5,visibility:1,vibration:true});await LocalNotifications.registerActionTypes({types:[{id:'TASK_ACTIONS',actions:[{id:'complete',title:'Completar'},{id:'snooze_10',title:'Posponer 10 min'},{id:'snooze_60',title:'Posponer 1 hora'}]}]});await LocalNotifications.addListener('localNotificationActionPerformed',async event=>{const id=event.notification?.extra?.reminderId;if(!id)return;if(event.actionId==='complete')await completeFromNotification(id);if(event.actionId==='snooze_10')await snoozeNotification(id,10);if(event.actionId==='snooze_60')await snoozeNotification(id,60)});const Alarm=globalThis.Capacitor?.Plugins?.Alarm;if(Alarm){const pending=await Alarm.consumeActions();for(const action of pending.actions||[]){if(action.action==='complete')await completeFromNotification(action.taskId);if(action.action==='skip')await skipOccurrence(action.taskId)}for(const item of state.tasks.filter(x=>x.priority==='high'&&!x.completed&&toDateTime(x)>new Date()))await Alarm.schedule(alarmPayload(item))}try{const exact=await LocalNotifications.checkExactNotificationSetting();if(exact.exact_alarm!=='granted')console.info('Las alarmas exactas están desactivadas en Android.')}catch{}}catch(e){console.warn('No se pudieron iniciar las notificaciones',e)}}
async function cancel(item){try{if(globalThis.Capacitor?.isNativePlatform?.()){const LocalNotifications=await localNotificationsPlugin();await LocalNotifications.cancel({notifications:[{id:hash(item.id+':due')},{id:hash(item.id+':early')},{id:hash(item.id+':snooze')}]});const Alarm=globalThis.Capacitor?.Plugins?.Alarm;if(Alarm)await Alarm.cancel({taskId:item.id})}}catch{}}
$('#taskForm').addEventListener('submit',async e=>{e.preventDefault();const id=$('#taskId').value,item={id:id||uid(),title:$('#titleInput').value.trim(),notes:$('#taskNotes').value.trim(),date:$('#dateInput').value,time:$('#timeInput').value,priority:$('#priorityInput').value,repeat:$('#repeatInput').value,repeatDays:$$('[name="repeatDay"]:checked').map(x=>Number(x.value)),repeatInterval:Number($('#repeatInterval').value||1),repeatUnit:$('#repeatUnit').value,personId:$('#personInput').value,reminderMinutes:Number($('#reminderMinutes').value||0),tags:[...new Set($('#tagsInput').value.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean))],completed:false,createdAt:new Date().toISOString()};if(item.repeat==='custom_days'&&!item.repeatDays.length)return $('#taskError').textContent='Selecciona por lo menos un día de repetición.';const error=validateReminder({...item,id});if(error)return $('#taskError').textContent=error;const i=state.tasks.findIndex(x=>x.id===item.id);if(i>=0){await cancel(state.tasks[i]);item.completed=state.tasks[i].completed;item.createdAt=state.tasks[i].createdAt;state.tasks[i]=item}else state.tasks.push(item);save();notify(item);e.target.closest('dialog').close();renderAll();toast('Tarea guardada')});
