function setupSecurityUi(){const card=document.createElement('section');card.className='settings-card security-card';card.innerHTML='<div><p class="eyebrow">SEGURIDAD</p><h2>Bloqueo de la aplicación</h2><p>Protege tu agenda con la huella, rostro, PIN, patrón o contraseña configurados en el teléfono.</p></div><div class="security-row"><div><b id="lockStatus">Disponible en la aplicación Android</b><small>Las llaves de IA se guardarán cifradas por Android.</small></div><button id="toggleAppLock" type="button" class="primary">Activar bloqueo</button></div><p id="securityResult" class="form-help" aria-live="polite"></p>';$('.backup-card').before(card);const overlay=document.createElement('div');overlay.id='lockOverlay';overlay.className='lock-overlay';overlay.hidden=true;overlay.innerHTML=`<div class="lock-box"><div class="lock-icon">${icon('lock-key','fill')}</div><h2>Luna Agenda está bloqueada</h2><p>Confirma tu identidad para continuar.</p><button id="unlockApp" class="primary">Desbloquear</button></div>`;document.body.append(overlay)}
