async function saveAiAndPreferences(resultSelector='#settingsResult'){state.ai=collectAiSettings();state.preferences={defaultPriority:$('#defaultPriority').value,defaultReminderMinutes:Number($('#defaultReminderMinutes').value||0),customMemory:$('#customMemory').value.trim()};try{await persistAiSettings();await storage.saveSetting('preferences',state.preferences);scheduleCloudBackup();updateAiStatus();$(resultSelector).textContent='Configuración guardada.';toast('Configuración guardada');processChatQueue()}catch(error){$(resultSelector).textContent=error.message||'No se pudo proteger la configuración.'}}
$('#aiProvider').onchange=e=>{const p=presets[e.target.value];if(p){$('#aiEndpoint').value=p.endpoint;$('#aiModel').value=p.model}};$('#toggleKey').onclick=()=>{$('#aiKey').type=$('#aiKey').type==='password'?'text':'password'};$('#toggleTranscriptionKey').onclick=()=>{$('#transcriptionKey').type=$('#transcriptionKey').type==='password'?'text':'password'};$('#aiSettings').onsubmit=e=>{e.preventDefault();saveAiAndPreferences()};$('#memorySettings').onsubmit=e=>{e.preventDefault();saveAiAndPreferences('#memoryResult')};$('#transcriptionSettings').onsubmit=e=>{e.preventDefault();saveAiAndPreferences('#transcriptionResult')};
const tools=[{type:'function',function:{name:'crear_tarea',description:'Crea una tarea',parameters:{type:'object',properties:{title:{type:'string'},date:{type:'string',description:'YYYY-MM-DD'},time:{type:'string',description:'HH:mm'},notes:{type:'string'},priority:{type:'string',enum:['low','medium','high']},tags:{type:'array',items:{type:'string'}},personName:{type:'string'}},required:['title','date','time']}}},{type:'function',function:{name:'buscar_tareas',description:'Busca tareas para consultarlas o modificarlas',parameters:{type:'object',properties:{query:{type:'string'},pendingOnly:{type:'boolean'}}}}},{type:'function',function:{name:'actualizar_tarea',description:'Modifica una tarea encontrada previamente. Envía solamente los campos que cambian. Si cambias la fecha o la hora de una tarea completada, se reabre automáticamente como pendiente.',parameters:{type:'object',properties:{id:{type:'string'},title:{type:'string'},date:{type:'string'},time:{type:'string'},notes:{type:'string'},priority:{type:'string',enum:['low','medium','high']},tags:{type:'array',items:{type:'string'}},personName:{type:'string'}},required:['id']}}},{type:'function',function:{name:'completar_tarea',description:'Completa una tarea encontrada previamente',parameters:{type:'object',properties:{id:{type:'string'}},required:['id']}}},{type:'function',function:{name:'crear_persona',description:'Registra una persona',parameters:{type:'object',properties:{name:{type:'string'},email:{type:'string'},phone:{type:'string'}},required:['name']}}},{type:'function',function:{name:'crear_nota',description:'Crea una nota',parameters:{type:'object',properties:{title:{type:'string'},content:{type:'string'}},required:['title','content']}}}];
tools.push({type:'function',function:{name:'consultar_hora_actual',description:'Obtiene la fecha y hora local exactas para calcular expresiones relativas como en 15 minutos o dentro de dos horas',parameters:{type:'object',properties:{}}}});
const taskSearchTool=tools.find(x=>x.function.name==='buscar_tareas');taskSearchTool.function.description='Consulta tareas, recordatorios, pendientes o actividades usando un periodo real de fechas, estado y texto opcional. Para hoy, mañana, esta semana, un día o un mes, usa dateFrom y dateTo; no envíes la fecha dentro de query.';Object.assign(taskSearchTool.function.parameters.properties,{dateFrom:{type:'string',description:'Primer día incluido, en YYYY-MM-DD'},dateTo:{type:'string',description:'Último día incluido, en YYYY-MM-DD'},status:{type:'string',enum:['pending','completed','all'],description:'Estado de las tareas; usa all si el usuario no limita el estado'}});
for(const name of ['crear_tarea','actualizar_tarea'])Object.assign(tools.find(x=>x.function.name===name).function.parameters.properties,{repeat:{type:'string',enum:['none','daily','weekly','monthly','custom_days','interval','last_day'],description:'Recurrencia de la tarea'},repeatDays:{type:'array',items:{type:'integer',minimum:0,maximum:6},description:'Días: domingo 0, lunes 1, martes 2, miércoles 3, jueves 4, viernes 5, sábado 6'},repeatInterval:{type:'integer',minimum:1},repeatUnit:{type:'string',enum:['days','weeks','months']}});
tools.find(x=>x.function.name==='crear_persona').function.parameters.required=['name'];tools.find(x=>x.function.name==='crear_persona').function.description='Registra una persona; el teléfono es opcional si el usuario indica que no lo tiene o desea omitirlo';
Object.assign(tools.find(x=>x.function.name==='crear_persona').function.parameters.properties,{relationship:{type:'string'},aliases:{type:'string'},birthday:{type:'string'},address:{type:'string'},company:{type:'string'},notes:{type:'string'}});
tools.push({type:'function',function:{name:'buscar_personas',description:'Busca localmente personas por nombre, relación, apodo, teléfono, correo, empresa, dirección o información adicional. Úsala siempre que el usuario mencione o pregunte por una persona; devuelve como máximo cinco coincidencias.',parameters:{type:'object',properties:{query:{type:'string',description:'Palabras naturales del usuario, por ejemplo: mi hermano, Sonia, mi contadora o últimos dígitos del teléfono'}},required:['query']}}});
tools.push({type:'function',function:{name:'actualizar_persona',description:'Actualiza los datos de una persona encontrada previamente',parameters:{type:'object',properties:{id:{type:'string'},name:{type:'string'},relationship:{type:'string'},aliases:{type:'string'},phone:{type:'string'},email:{type:'string'},birthday:{type:'string'},address:{type:'string'},company:{type:'string'},notes:{type:'string'}},required:['id']}}});
function runTool(name,a){if(name==='consultar_hora_actual'){const now=new Date();return{isoLocal:`${localDateKey(now)}T${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,fecha:now.toLocaleDateString('es-MX',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),hora:now.toLocaleTimeString('es-MX',{hour:'numeric',minute:'2-digit'}),zona:Intl.DateTimeFormat().resolvedOptions().timeZone}}if(name==='crear_tarea'){const p=state.people.find(x=>x.name.toLowerCase()===a.personName?.toLowerCase());const x={id:uid(),title:a.title,date:a.date,time:a.time,notes:a.notes||'',priority:a.priority||state.preferences.defaultPriority||'medium',repeat:'none',reminderMinutes:Number(state.preferences.defaultReminderMinutes||0),tags:a.tags||[],personId:p?.id||'',completed:false,createdAt:new Date().toISOString()};const error=validateReminder(x);if(error)return{error};state.tasks.push(x);save();notify(x);renderAll();return{success:true,id:x.id}}if(name==='buscar_tareas')return state.tasks.filter(x=>(!a.pendingOnly||!x.completed)&&(!a.query||(x.title+' '+x.notes).toLowerCase().includes(a.query.toLowerCase()))).slice(0,20);if(name==='actualizar_tarea'){const x=state.tasks.find(t=>t.id===a.id);if(!x)return{error:'No encontrada'};const reopened=shouldReopenOnReschedule(x,a);cancel(x);for(const key of ['title','date','time','notes','priority','tags'])if(a[key]!==undefined)x[key]=a[key];if(reopened)x.completed=false;if(a.personName!==undefined)x.personId=state.people.find(p=>p.name.toLowerCase()===a.personName.toLowerCase())?.id||'';const error=validateReminder({...x,id:x.id});if(error)return{error};save();notify(x);renderAll();return{success:true,reopened}}if(name==='completar_tarea'){const x=state.tasks.find(t=>t.id===a.id);if(!x)return{error:'No encontrada'};x.completed=true;cancel(x);save();renderAll();return{success:true}}if(name==='crear_persona'){const p={id:uid(),name:a.name,email:a.email||'',phone:a.phone||'',color:'#6750a4'};state.people.push(p);save();renderAll();return{success:true,id:p.id}}if(name==='crear_nota'){const n={id:uid(),title:a.title,content:a.content,color:'purple',updatedAt:new Date().toISOString()};state.notes.push(n);save();renderAll();return{success:true,id:n.id}}return{error:'Herramienta desconocida'}}
const executeBaseTool=runTool;
runTool=function(name,args){const result=executeBaseTool(name,args);if(!result?.error&&['crear_tarea','actualizar_tarea'].includes(name)&&args.repeat!==undefined){const task=state.tasks.find(x=>x.id===(result.id||args.id));if(task){task.repeat=args.repeat||'none';task.repeatDays=args.repeatDays||[];task.repeatInterval=Math.max(1,Number(args.repeatInterval||1));task.repeatUnit=args.repeatUnit||'days';save();cancel(task).then(()=>notify(task));renderAll()}}return result};
const executeTaskTool=runTool;
runTool=function(name,args){if(name==='buscar_tareas')return searchReminders(state.tasks,args).slice(0,50);if(name==='buscar_personas')return findPeople(state.people,args.query).slice(0,5).map(publicPerson);if(name==='crear_persona'){const existing=findPeople(state.people,args.name).find(p=>p.name.toLowerCase()===args.name.toLowerCase());if(existing)return{error:'Ya existe una persona con ese nombre',person:publicPerson(existing)};const p=enrichPerson({id:uid(),name:args.name,relationship:args.relationship||'',aliases:args.aliases||'',phone:args.phone||'',email:args.email||'',birthday:args.birthday||'',address:args.address||'',company:args.company||'',notes:args.notes||'',color:'#6750a4'});state.people.push(p);save();renderAll();return{success:true,id:p.id}}if(name==='actualizar_persona'){const p=state.people.find(person=>person.id===args.id);if(!p)return{error:'No encontrada'};for(const key of ['name','relationship','aliases','phone','email','birthday','address','company','notes'])if(args[key]!==undefined)p[key]=args[key];Object.assign(p,enrichPerson(p));save();renderAll();return{success:true,person:publicPerson(p)}}if(['crear_tarea','actualizar_tarea'].includes(name)&&args.personName){const matches=findPeople(state.people,args.personName);if(matches.length===1)args={...args,personName:matches[0].name}}return executeTaskTool(name,args)};
async function aiRequest(messages,withTools=true){if(!state.ai.key)throw new Error('Configura primero la llave API.');if(messages[0]?.role==='system')messages[0]={...messages[0],content:messages[0].content+personRules()+'\nLas palabras tareas, recordatorios, pendientes y actividades se refieren a los mismos elementos de la agenda. Para cualquier consulta temporal, calcula el primer y último día solicitados y busca usando el intervalo de fechas. Nunca busques una fecha como texto del título. Si el usuario pide esta semana, consulta todo el intervalo semanal en una sola búsqueda; no hagas una búsqueda textual separada por cada día.'};const body={model:state.ai.model,messages,temperature:.2};if(withTools){body.tools=tools;body.tool_choice='auto'}const res=await fetch(state.ai.endpoint,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${state.ai.key}`,'HTTP-Referer':location.origin,'X-Title':'Luna Agenda'},body:JSON.stringify(body)});let data={};try{data=await res.json()}catch{}if(!res.ok){const error=new Error(data.error?.message||`Error HTTP ${res.status}`);error.status=res.status;error.retryable=res.status===408||res.status===429||res.status>=500;throw error}if(!data.choices?.[0]?.message){const error=new Error('El servidor no devolvió una respuesta válida.');error.retryable=true;throw error}return data.choices[0].message}
function plainText(text=''){return text.replaceAll('*','').replaceAll('_','').replaceAll('`','').replace(/^#{1,6}\s+/gm,'').replace(/^\s*[-•]\s+/gm,'').trim()}
async function agent(history){const now=new Date(),today=localDateKey(now),currentTime=now.toLocaleTimeString('es-MX',{hour:'numeric',minute:'2-digit'}),rules=['Te llamas Luna. Eres la asistente personal de Luna Agenda: amable, servicial, cercana y con personalidad propia.','Habla en primera persona como Luna cuando sea natural, pero no repitas tu nombre innecesariamente.','La fecha y hora local internas son '+today+' a las '+currentTime+'. El usuario se llama '+(state.ai.ownerName||'usuario')+'.','Cuando el usuario diga en cierta cantidad de minutos u horas, consulta la hora actual y calcula la fecha y hora exactas antes de crear la tarea. No preguntes la hora si puedes calcularla.','Conserva y usa todo el contexto de la conversación. Si antes se mencionó el título, la fecha, la hora o la persona de una tarea, recuérdalo y no vuelvas a preguntarlo.','Interpreta expresiones como esa tarea, la anterior, cámbiala o edítala usando el contexto reciente. Antes de editar, busca la tarea y utiliza su identificador solamente de forma interna.','Cuando el usuario pida reagendar, posponer o mover una tarea, actualiza su fecha u hora sin preguntar si debe reabrirse. Si estaba completada, la aplicación la devolverá automáticamente a pendiente.','Responde siempre en español y solamente con texto plano. No uses Markdown, asteriscos, viñetas, encabezados, tablas, bloques de código ni símbolos para dar formato.','Nunca menciones identificadores internos, IDs, nombres de herramientas, JSON, endpoints, parámetros ni formatos técnicos de fecha u hora.','Expresa las fechas de forma natural, por ejemplo: mañana, este viernes, 25 de agosto o a las 8 de la mañana.','Sé práctica. Si puedes completar la solicitud con la información disponible, hazlo sin preguntar.','No solicites datos opcionales. Para una tarea solo son indispensables el título, la fecha y la hora. La persona, las etiquetas, la prioridad y las notas son opcionales.','Si falta un dato indispensable, haz solamente una pregunta por mensaje y espera la respuesta antes de pedir otro dato.','Haz preguntas breves y naturales, por ejemplo: Perfecto, ¿a qué hora te gustaría que te lo recuerde?','No vuelvas a pedir datos que el usuario ya proporcionó.','Solo pregunta para aclarar cuando actuar podría modificar el elemento equivocado.','Usa las herramientas silenciosamente. Confirma los resultados de forma breve y humana.','Los identificadores que recibas son exclusivamente internos y jamás debes mostrarlos al usuario.'].join('\\n');const messages=[{role:'system',content:rules},...history];let mutationPerformed=false;const mutations=new Set(['crear_tarea','actualizar_tarea','completar_tarea','crear_persona','actualizar_persona','crear_nota']);for(let i=0;i<5;i++){let msg;try{msg=await aiRequest(messages)}catch(error){if(mutationPerformed)return'Realicé la acción solicitada, pero la conexión se interrumpió antes de generar la confirmación.';throw error}messages.push(msg);if(!msg.tool_calls?.length)return plainText(msg.content||'Listo.');for(const call of msg.tool_calls){let args={};try{args=JSON.parse(call.function.arguments)}catch{}const result=runTool(call.function.name,args);if(!result?.error&&mutations.has(call.function.name))mutationPerformed=true;messages.push({role:'tool',tool_call_id:call.id,content:JSON.stringify(result)})}}return'Completé las acciones disponibles.'}
function addMessage(message){const d=document.createElement('div');d.className=`message ${message.role} ${message.status||''}`;d.dataset.messageId=message.id||'';const content=document.createElement('span');content.textContent=message.content;d.append(content);if(message.role==='user'&&message.status&&message.status!=='sent'){const status=document.createElement('small');status.className='message-delivery';status.textContent=message.status==='sending'?'Enviando…':message.status==='failed'?'No se pudo enviar':'Pendiente de envío';d.append(status);if(message.status!=='sending'){const retry=document.createElement('button');retry.type='button';retry.dataset.retryMessage=message.id;retry.textContent='Reintentar';d.append(retry)}}$('#chatMessages').append(d);$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;return d}
function renderChat(){if(!state.chat.length)return;$('#chatMessages').innerHTML='';state.chat.forEach(addMessage)}
