$('#mobileNewChat').onclick=()=>$('#newChat').click();
let recorder,audioParts=[];async function transcribeAudio(blob){const key=state.ai.transcriptionKey||$('#transcriptionKey').value.trim();const endpoint=state.ai.transcriptionEndpoint||$('#transcriptionEndpoint').value.trim();const model=state.ai.transcriptionModel||$('#transcriptionModel').value.trim();if(!key||!endpoint||!model)throw new Error('Configura primero la transcripción de voz.');const form=new FormData();form.append('file',blob,'mensaje.webm');form.append('model',model);form.append('language','es');const res=await fetch(endpoint,{method:'POST',headers:{Authorization:'Bearer '+key},body:form});const data=await res.json();if(!res.ok)throw new Error(data.error?.message||'No se pudo transcribir el audio.');return data.text||data.transcript||''}
async function requestMicrophonePermission(){const plugin=globalThis.Capacitor?.Plugins?.MicrophonePermission;if(!plugin)return true;const result=await plugin.request();if(!result.granted)throw new Error('Permiso de micrófono denegado. Actívalo en los ajustes de la aplicación.');return true}
$('#recordAudio').onclick=async()=>{const button=$('#recordAudio');if(recorder?.state==='recording'){recorder.stop();button.classList.remove('recording');button.innerHTML=icon('microphone');return}try{await requestMicrophonePermission();if(!navigator.mediaDevices?.getUserMedia)throw new Error('Este dispositivo no ofrece acceso web al micrófono.');const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});audioParts=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)audioParts.push(e.data)};recorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());button.disabled=true;button.innerHTML=icon('spinner');try{const text=await transcribeAudio(new Blob(audioParts,{type:recorder.mimeType||'audio/webm'}));$('#chatInput').value=text;$('#chatInput').focus();toast('Audio transcrito')}catch(e){toast(e.message)}finally{button.disabled=false;button.innerHTML=icon('microphone')}};recorder.start();button.classList.add('recording');button.innerHTML=icon('stop','fill');toast('Grabando… toca de nuevo para terminar')}catch(e){console.warn('Error de micrófono',e);toast(e.message||'No fue posible acceder al micrófono.')}};
let processingChatQueue=false;
async function saveChatQueue(){await storage.saveChat(state.chat);scheduleCloudBackup()}
async function processChatQueue(){if(processingChatQueue||!navigator.onLine||!state.ai.key)return;processingChatQueue=true;try{while(navigator.onLine){const pending=nextPendingMessage(state.chat);if(!pending)break;pending.status='sending';delete pending.error;await saveChatQueue();renderChat();try{const answer=await agent(historyThrough(state.chat,pending.id));const index=state.chat.findIndex(message=>message.id===pending.id);if(index<0)continue;pending.status='sent';state.chat.splice(index+1,0,{id:uid(),role:'assistant',content:answer,replyTo:pending.id,createdAt:new Date().toISOString()});await saveChatQueue();renderChat()}catch(error){const retryable=isRetryableDeliveryError(error,navigator.onLine);pending.status=retryable?'pending':'failed';pending.error=error.message||'No se pudo enviar.';await saveChatQueue();renderChat();toast(retryable?'Mensaje guardado. Se enviará cuando vuelva Internet.':pending.error);break}}}finally{processingChatQueue=false}}
$('#chatForm').onsubmit=async e=>{e.preventDefault();const input=$('#chatInput'),text=input.value.trim();if(!text)return;const message=queuedMessage(text);state.chat.push(message);input.value='';await saveChatQueue();renderChat();if(!navigator.onLine){toast('Sin conexión: mensaje pendiente de envío.');return}processChatQueue()};
$('#chatMessages').addEventListener('click',e=>{const button=e.target.closest('[data-retry-message]');if(!button)return;const message=state.chat.find(item=>item.id===button.dataset.retryMessage);if(!message)return;message.status='pending';delete message.error;saveChatQueue().then(()=>{renderChat();processChatQueue()})});
addEventListener('online',()=>{toast('Conexión recuperada. Enviando mensajes pendientes…');processChatQueue()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)processChatQueue()});
$('#testAi').onclick=async()=>{state.ai=collectAiSettings();$('#settingsResult').textContent='Probando…';try{const m=await aiRequest([{role:'user',content:'Responde solamente: conexión correcta'}],false);$('#settingsResult').textContent=m.content||'Conexión correcta.'}catch(e){$('#settingsResult').textContent='Error: '+e.message}};
const secureVault=()=>globalThis.Capacitor?.Plugins?.SecureVault;
async function persistAiSettings(){const plugin=secureVault(),plain={...state.ai};if(plugin){await plugin.store({apiKey:plain.key||'',transcriptionKey:plain.transcriptionKey||''});delete plain.key;delete plain.transcriptionKey}await storage.saveSetting('ai',plain)}
async function loadSecureKeys(){const plugin=secureVault();if(!plugin)return;const secrets=await plugin.read();state.ai.key=secrets.apiKey||state.ai.key||'';state.ai.transcriptionKey=secrets.transcriptionKey||state.ai.transcriptionKey||'';loadAi();updateAiStatus();processChatQueue()}
async function refreshLockUi(){const plugin=secureVault();if(!plugin){$('#toggleAppLock').disabled=true;return}const status=await plugin.status();$('#lockStatus').textContent=status.enabled?'Bloqueo activado':'Bloqueo desactivado';$('#toggleAppLock').textContent=status.enabled?'Desactivar bloqueo':'Activar bloqueo';$('#lockOverlay').hidden=!status.enabled||status.unlocked;return status}
async function unlockApplication(){const plugin=secureVault();if(!plugin)return;$('#securityResult').textContent='Esperando confirmación…';try{await plugin.authenticate();await loadSecureKeys();await refreshLockUi();$('#securityResult').textContent='Aplicación desbloqueada.'}catch(error){$('#securityResult').textContent=error.message||'No se pudo confirmar la identidad.'}}
async function initSecurity(){const plugin=secureVault();if(!plugin)return;const status=await refreshLockUi();if(status.enabled&&!status.unlocked)await unlockApplication();else await loadSecureKeys()}
$('#unlockApp').onclick=unlockApplication;$('#toggleAppLock').onclick=async()=>{const plugin=secureVault();if(!plugin)return toast('Esta función requiere la APK de Android.');try{const status=await plugin.status();if(status.enabled){if(!status.unlocked)await plugin.authenticate();await plugin.setEnabled({enabled:false});$('#securityResult').textContent='Bloqueo desactivado.'}else{await plugin.authenticate();await plugin.setEnabled({enabled:true});$('#securityResult').textContent='Bloqueo activado.'}await loadSecureKeys();await refreshLockUi()}catch(error){$('#securityResult').textContent=error.message||'No se pudo cambiar el bloqueo.'}};
document.addEventListener('visibilitychange',async()=>{const plugin=secureVault();if(!plugin)return;if(document.hidden){await plugin.lock();const status=await refreshLockUi();if(status.enabled){state.ai.key='';state.ai.transcriptionKey='';loadAi()}}else{const status=await refreshLockUi();if(status.enabled&&!status.unlocked)await unlockApplication()}});
function backupPayload(includeSecrets=false){const ai={...state.ai};if(!includeSecrets){delete ai.key;delete ai.transcriptionKey}return{app:'recordatorios-capacitor',version:1,exportedAt:new Date().toISOString(),data:{tasks:state.tasks,people:state.people,notes:state.notes,chat:state.chat,preferences:state.preferences,ai,theme:document.documentElement.classList.contains('dark')?'dark':'light'},includesSecrets:includeSecrets}}
async function downloadFile(file,title){const nativeShare=globalThis.Capacitor?.Plugins?.BackupStorage;if(globalThis.Capacitor?.isNativePlatform?.()&&nativeShare){await nativeShare.share({content:await file.text(),fileName:file.name,title});return}if(navigator.share){try{await navigator.share({title,files:[file]});return}catch(error){if(error.name==='AbortError')throw error;if(navigator.canShare?.({files:[file]}))throw error}}const url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=file.name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportAiConfiguration(){state.ai=collectAiSettings();state.preferences={defaultPriority:$('#defaultPriority').value,defaultReminderMinutes:Number($('#defaultReminderMinutes').value||0),customMemory:$('#customMemory').value.trim()};const payload={app:'recordatorios-capacitor-ai-config',version:1,exportedAt:new Date().toISOString(),warning:'PRIVADO: contiene llaves API',ai:state.ai,preferences:state.preferences};const file=new File([JSON.stringify(payload,null,2)],`configuracion-privada-luna-agenda-${localDateKey()}.json`,{type:'application/json'});try{await downloadFile(file,'Configuración privada de Luna Agenda');$('#quickConfigResult').textContent='Archivo privado creado. Guárdalo en un lugar seguro.';toast('Configuración exportada')}catch(error){if(error.name!=='AbortError'){$('#quickConfigResult').textContent='No se pudo exportar la configuración.';toast('No se pudo exportar')}}}
async function importAiConfiguration(file){const value=JSON.parse(await file.text());if(value?.app!=='recordatorios-capacitor-ai-config'||value.version!==1||!value.ai||typeof value.ai!=='object')throw new Error('El archivo no es una configuración compatible.');if(!confirm('Se reemplazarán tus llaves, modelos y memorias actuales. ¿Continuar?'))return;state.ai={...state.ai,...value.ai};state.preferences={defaultPriority:'medium',defaultReminderMinutes:0,customMemory:'',...(value.preferences||{})};await persistAiSettings();await storage.saveSetting('preferences',state.preferences);loadAi();updateAiStatus();$('#quickConfigResult').textContent='Configuración importada correctamente.';toast('Configuración importada')}
$('#exportAiConfig').onclick=exportAiConfiguration;$('#importAiConfig').onclick=()=>$('#aiConfigFile').click();$('#aiConfigFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{await importAiConfiguration(file)}catch(error){$('#quickConfigResult').textContent=error instanceof SyntaxError?'El archivo no contiene datos válidos.':error.message;toast('No se pudo importar')}finally{e.target.value=''}};
async function downloadBackup(){const includeSecrets=$('#includeSecrets').checked,payload=backupPayload(includeSecrets),stamp=localDateKey(),file=new File([JSON.stringify(payload,null,2)],`respaldo-luna-agenda-${stamp}.json`,{type:'application/json'});try{await downloadFile(file,'Respaldo de Luna Agenda');$('#backupResult').textContent='Elige dónde guardar o compartir el respaldo.';toast('Selecciona un destino')}catch(e){if(e.name!=='AbortError'){$('#backupResult').textContent=e.message||'No se pudo crear el respaldo.';toast('No se pudo exportar')}}}
function validateBackup(value){if(!value||value.app!=='recordatorios-capacitor'||value.version!==1||!value.data)throw new Error('Este archivo no es un respaldo compatible.');for(const key of ['tasks','people','notes','chat'])if(!Array.isArray(value.data[key]))throw new Error('El respaldo está incompleto o dañado.');if(value.data.preferences!==undefined&&(typeof value.data.preferences!=='object'||Array.isArray(value.data.preferences)))throw new Error('Las preferencias del respaldo no son válidas.');return value.data}
async function restoreBackup(file){const value=JSON.parse(await file.text()),data=validateBackup(value);if(!confirm(`Se reemplazarán los datos actuales por ${data.tasks.length} tarea(s), ${data.people.length} persona(s) y ${data.notes.length} nota(s). ¿Continuar?`))return;for(const task of state.tasks)await cancel(task);state.tasks=data.tasks.map(x=>({...x,tags:Array.isArray(x.tags)?x.tags:[],personId:x.personId||'',reminderMinutes:Number(x.reminderMinutes||0)}));state.people=data.people.map(enrichPerson);state.notes=data.notes;state.chat=normalizeChat(data.chat);state.preferences={defaultPriority:'medium',defaultReminderMinutes:0,customMemory:'',...(data.preferences||{})};const existingKeys={key:state.ai.key||'',transcriptionKey:state.ai.transcriptionKey||''};state.ai={...state.ai,...(data.ai||{})};if(!data.ai?.key)state.ai.key=existingKeys.key;if(!data.ai?.transcriptionKey)state.ai.transcriptionKey=existingKeys.transcriptionKey;await storage.saveCollections({tasks:state.tasks,people:state.people,notes:state.notes});await storage.saveChat(state.chat);await persistAiSettings();await storage.saveSetting('preferences',state.preferences);if(data.theme){await storage.saveSetting('theme',data.theme);document.documentElement.classList.toggle('dark',data.theme==='dark')}scheduleCloudBackup();loadAi();renderAll();$('#chatMessages').innerHTML='<div class="message assistant">Hola, soy Luna. ¿Qué organizamos hoy?</div>';renderChat();for(const task of state.tasks)await notify(task);$('#backupResult').textContent='Respaldo restaurado correctamente.';toast('Datos restaurados');processChatQueue()}
$('#exportBackup').onclick=downloadBackup;$('#importBackup').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;$('#backupResult').textContent='Restaurando…';try{await restoreBackup(file)}catch(err){$('#backupResult').textContent=err instanceof SyntaxError?'El archivo no contiene un respaldo válido.':err.message;toast('No se pudo restaurar')}finally{e.target.value=''}};
const backupStorage=()=>globalThis.Capacitor?.Plugins?.BackupStorage;
async function updateDriveStatus(){const plugin=backupStorage(),panel=$('.drive-panel');if(!plugin){$('#driveStatus').textContent='Disponible en la aplicación Android.';$('#connectDrive').disabled=true;return}try{const status=await plugin.status();panel.classList.toggle('connected',status.connected);$('#driveStatus').textContent=status.connected?'Carpeta conectada. Pulsa Guardar ahora para comprobarla.':'Selecciona una carpeta de Google Drive.';$('#connectDrive').textContent=status.connected?'Cambiar carpeta':'Conectar carpeta';$('#backupDriveNow').hidden=!status.connected;$('#restoreDrive').hidden=!status.connected;$('#disconnectDrive').hidden=!status.connected}catch{$('#driveStatus').textContent='No se pudo consultar la conexión.'}}
async function writeDriveBackup(showResult=false){const plugin=backupStorage();if(!plugin)return false;const status=await plugin.status();if(!status.connected)return false;const result=await plugin.write({content:JSON.stringify(backupPayload(false),null,2)});const when=new Date(result.savedAt||Date.now()).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'});$('#driveStatus').textContent='Último respaldo: '+when;if(showResult)toast('Respaldo guardado en Drive');return true}
function scheduleCloudBackup(){clearTimeout(scheduleCloudBackup.timer);scheduleCloudBackup.timer=setTimeout(()=>writeDriveBackup().catch(error=>{console.warn('No se pudo actualizar el respaldo automático',error);$('#driveStatus').textContent='No se pudo actualizar el respaldo automático.'}),1200)}
$('#connectDrive').onclick=async()=>{const plugin=backupStorage();if(!plugin)return toast('Esta función requiere la APK de Android.');try{await plugin.chooseFolder();await updateDriveStatus();await writeDriveBackup(true)}catch(error){if(!/seleccionó/.test(error.message||'')){const message=error.message||'No se pudo escribir en la carpeta.';$('#driveStatus').textContent=message;toast(message)}}};
$('#backupDriveNow').onclick=async()=>{try{await writeDriveBackup(true)}catch(error){const message=error.message||'No se pudo guardar el respaldo.';$('#driveStatus').textContent=message;$('#backupResult').textContent=message;toast(message)}};
$('#restoreDrive').onclick=async()=>{if(!confirm('¿Restaurar el respaldo de Drive y reemplazar los datos actuales?'))return;try{const result=await backupStorage().read(),file=new File([result.content],'recordatorios-respaldo.json',{type:'application/json'});await restoreBackup(file)}catch(error){$('#backupResult').textContent=error.message||'No se pudo restaurar desde Drive.';toast('No se pudo restaurar')}};
$('#disconnectDrive').onclick=async()=>{if(!confirm('¿Desconectar la carpeta? El archivo que ya está en Drive no se eliminará.'))return;await backupStorage().disconnect();await updateDriveStatus();toast('Carpeta desconectada')};
$('#deleteAllData').onclick=async()=>{if(!confirm('¿Borrar todas las tareas, personas, notas, chats, preferencias y llaves de este dispositivo? Esta acción no se puede deshacer.'))return;for(const task of state.tasks)await cancel(task);await storage.clearAll();const plugin=secureVault();if(plugin)await plugin.store({apiKey:'',transcriptionKey:''});location.reload()};
let nativeStatusBar;
async function updateSystemBar(){if(!globalThis.Capacitor?.isNativePlatform?.())return;try{nativeStatusBar ||=globalThis.Capacitor?.Plugins?.StatusBar||(await import('@capacitor/status-bar')).StatusBar;const dark=document.documentElement.classList.contains('dark');await nativeStatusBar.setOverlaysWebView({overlay:true});await nativeStatusBar.setBackgroundColor({color:dark?'#111116':'#f8f9fb'});await nativeStatusBar.setStyle({style:dark?'LIGHT':'DARK'});await nativeStatusBar.show()}catch(e){console.warn('No se pudo configurar la barra del sistema',e)}}
async function initMobileUi(){let maximumHeight=Math.max(window.innerHeight,window.visualViewport?.height||0);const updateViewport=()=>{const visible=Math.round(window.visualViewport?.height||window.innerHeight);maximumHeight=Math.max(maximumHeight,window.innerHeight,visible);document.documentElement.style.setProperty('--visible-height',`${visible}px`);document.body.classList.toggle('keyboard-open',maximumHeight-visible>140);requestAnimationFrame(()=>{$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight})};updateViewport();window.visualViewport?.addEventListener('resize',updateViewport);window.visualViewport?.addEventListener('scroll',updateViewport);window.addEventListener('orientationchange',()=>{maximumHeight=0;setTimeout(updateViewport,250)});if(!globalThis.Capacitor?.isNativePlatform?.())return;document.body.classList.add('native-platform');await updateSystemBar()}
loadAi();renderAll();renderChat();initMobileUi();initNativeNotifications();updateDriveStatus();initSecurity().then(processChatQueue);if('serviceWorker'in navigator&&!globalThis.Capacitor?.isNativePlatform?.())navigator.serviceWorker.register('./sw.js');
